"""Create a self-contained visual comparison with recovered original frame data."""
from pathlib import Path
import base64
import html
import json
import re
import sys


root = Path(sys.argv[1]).resolve()
data = json.loads((root / 'analysis-inventory.json').read_text(encoding='utf-8'))
provenance = json.loads((root / 'download-provenance.json').read_text(encoding='utf-8'))
sources = json.loads((root / 'source-provenance.json').read_text(encoding='utf-8'))
by_id = {item['item_id']: item for item in data}


def file_link(path, label):
    return f'<a href="{html.escape(Path(path).resolve().as_uri(), quote=True)}">{html.escape(label)}</a>'


names = {'3747497501': 'Regent FX Omnistar', '3747579486': '更多的角色特效', '3774274248': '更多的动作与特效',
         '3748964314': 'Lovecs VFX', '3747647777': 'Marisa 魔理沙'}
methods = {'3747497501': '预制帧 + 实时星点 + Shader', '3747579486': '程序化星阵 + 短序列帧',
           '3774274248': '角色位移 + 姿态复制 + 屏幕处理', '3748964314': 'GPU 粒子模板 + Marker 配置',
           '3747647777': 'Shader 光束 + 实时弹道 + 粒子'}
source_mapping = {'3747497501': sources[2], '3748964314': sources[0], '3747647777': sources[1]}
rows = []
for identifier in ('3747497501', '3747579486', '3774274248', '3748964314', '3747647777'):
    item = by_id[identifier]
    package = next(p for p in provenance['items'] if p['item_id'] == identifier)
    manifest = item['manifests'][0]
    source = source_mapping.get(identifier)
    github = f'<a href="{source["url"]}/tree/{source["commit"]}">{html.escape(source["name"])}</a><br><code>{source["commit"][:7]}</code>' if source else '未定位对应仓库<br><span class="dim">已反编译发布 DLL</span>'
    counts = item['recovered_counts']
    rows.append(f'<tr><th scope="row"><a href="{package["workshop_url"]}">{names[identifier]}</a><small>{manifest["version"]} · {package["bytes_on_disk"]/1048576:.2f} MiB</small></th><td>{methods[identifier]}</td><td>{counts.get(".tscn",0)} 场景 / {counts.get(".png",0)} PNG<br><span class="dim">{counts.get(".gdshader",0)} 外置 Shader</span></td><td>{github}</td></tr>')

sequences = []
specifications = [
    ('3747497501', '/alignment/', '储君 · Alignment', 30, 0, '42 张透明帧，825×600。场景还带一个结束空帧。这里查看主序列，不含准备星、声效或曝光。', True),
    ('3747579486', '/star_appear/', '更多的角色特效 · 敌人死亡', 30, 13, '61 张资源，260×260。实际播放器从资源第 13 帧开始，名义播放 1.6 秒；代码还叠加淡入淡出。', False),
    ('3774274248', '华丽收场/', '更多的动作与特效 · 华丽收场', 12.5, 0, '15 张透明帧，1920×1080。场景以 12.5 fps 播放，C# 在 1.2 秒后删除根节点。', False),
]
for identifier, key, name, fps, start, note, blank in specifications:
    group = next(g for g in by_id[identifier]['frame_groups'] if key in g['key'])
    ordered = sorted(group['paths'], key=lambda p: int(re.search(r'(\d+)\.png$', p)[1]))
    frames = ['data:image/png;base64,' + base64.b64encode((root / 'recovered' / identifier / path).read_bytes()).decode('ascii') for path in ordered]
    if blank:
        frames.append(None)
    sequences.append({'name': name, 'fps': fps, 'start': start, 'note': note, 'paths': ordered,
                      'origin': identifier, 'frames': frames})

doc = root.parents[2] / 'docs' / '19.创意工坊特效Mod解包与制作流程.md'
links = ''.join('<li>' + file_link(root / name, label) + '</li>' for name, label in [
    ('download-provenance.json', '下载来源、包大小和 SHA-256'), ('pck-inventory.json', '4,378 个原始条目和 MD5'),
    ('analysis-inventory.json', '恢复资源、节点和帧分组清单'), ('source-provenance.json', '三份源码的提交快照')])
link_doc = file_link(doc, '完整文字分析与源码阅读入口')

